command:
set +e
set -uo pipefail
# spawn runs task commands under bash -e; `set -uo pipefail` does not clear it (spawn#707).
export PATH=/opt/conda/bin:/usr/local/bin:$PATH TMPDIR=/tmp HOME=/tmp
cd /tmp
echo "== staged screen must match its pins =="
sha256sum -c fixture.sha256 || { echo "FAIL: the staged screen does not match its pins"; exit 1; }
echo "mageck $(mageck --version 2>&1 | tail -1); $(python3 -c 'import numpy,scipy;print("numpy",getattr(numpy,"__version__","?"),"scipy",getattr(scipy,"__version__","?"))' 2>&1)"
T0=$(date +%s)
mageck count -l library.txt -n screen --sample-label ctrl1,ctrl2,treat1,treat2,null1,null2 \
  --fastq ctrl1.fastq.gz ctrl2.fastq.gz treat1.fastq.gz treat2.fastq.gz null1.fastq.gz null2.fastq.gz > count.stdout 2>&1; R1=$?
T1=$(date +%s)
mageck test -k screen.count.txt -t treat1,treat2 -c ctrl1,ctrl2 --control-sgrna controls.txt --normcounts-to-file -n rra > rra.stdout 2>&1; R2=$?
mageck test -k screen.count.txt -t treat1,treat2 -c ctrl1,ctrl2 --control-sgrna controls.txt -n rra_rep > rra_rep.stdout 2>&1; R3=$?
mageck test -k screen.count.txt -t null1,null2 -c ctrl1,ctrl2 --control-sgrna controls.txt -n null > null.stdout 2>&1; R4=$?
T2=$(date +%s)
printf 'Samples\tbaseline\ttreatment\nctrl1\t1\t0\nctrl2\t1\t0\ntreat1\t1\t1\ntreat2\t1\t1\n' > design.txt
mageck mle -k screen.count.txt -d design.txt --control-sgrna controls.txt --threads 2 -n mle > mle.stdout 2>&1; R5=$?
T3=$(date +%s)
echo "rc: count $R1 ($((T1-T0))s), test $R2 rep $R3 null $R4 ($((T2-T1))s), mle $R5 ($((T3-T2))s)"
for r in $R1 $R2 $R3 $R4 $R5; do test "$r" = 0 || { echo "FAIL: a mageck step did not finish"; tail -20 *.stdout; exit 1; }; done
cat > check.py <<'PY'
import math, re, sys
ok = True
def rec(name, val, note=""):
    print("%-34s %s%s" % (name, str(val), ("   " + note) if note else ""))
def fail(msg):
    global ok
    print("FAIL: " + msg); ok = False
def table(path):
    rows = [l.rstrip("\n").split("\t") for l in open(path)]
    return rows[0], rows[1:]

# ---- count: the table must equal the planted counts exactly -------------------------------
th, tr = table("truth_counts.txt")
mh, mr = table("screen.count.txt")
SAMPLES = th[2:]
truth = {r[0]: (r[1], [int(x) for x in r[2:]]) for r in tr}
got = {r[0]: (r[1], [int(float(x)) for x in r[2:]]) for r in mr}
if mh[2:] != SAMPLES: fail("count table columns %s, expected %s" % (mh[2:], SAMPLES))
diff = [k for k in truth if got.get(k) != truth[k]] + [k for k in got if k not in truth]
rec("count_table_vs_planted", "%d sgRNAs, %d differ" % (len(got), len(diff)))
if len(got) != len(truth) or diff: fail("count table differs from the planted counts at %d sgRNAs (e.g. %s)" % (len(diff), diff[:3]))

# summary: reads, mapped, zero-count sgRNAs and Gini recomputed from the truth, not from MAGeCK
reads = {l.split("\t")[0]: int(l.split("\t")[1]) for l in open("truth_reads.txt").read().splitlines()[1:]}
sh, sr = table("screen.countsummary.txt")
logtxt = open("screen.log").read()
ginis = [float(x) for x in re.findall(r"giniindex\t(\S+)", logtxt)]
trims = re.findall(r"Auto determination of trim5 results: (\S+)", logtxt)
rec("auto_trim5", ",".join(trims), "(guide planted at offset 23)")
if trims != ["23"] * len(SAMPLES): fail("auto trim-5 did not find offset 23 in every sample")
for j, s in enumerate(SAMPLES):
    row = [r for r in sr if r[1] == s][0]
    col = [truth[k][1][j] for k in truth]
    mapped, zeros = sum(col), sum(1 for c in col if c == 0)
    # Gini as mean absolute difference, x n/(n-1) -- the sample form MAGeCK reports, on log(count+1)
    x = sorted(math.log(c + 1.0) for c in col); n = len(x)
    pre, mad = 0.0, 0.0
    for i, v in enumerate(x):
        mad += v * i - pre; pre += v
    g = (mad / (n * n * (sum(x) / n))) * n / (n - 1)
    gl = ginis[j]
    rec("summary_" + s, "reads %s mapped %s zero %s gini %s" % (row[2], row[3], row[6], row[7]),
        "(expect %d %d %d %.4g; |gini-log - mine| %.1e)" % (reads[s], mapped, zeros, g, abs(gl - g)))
    if int(row[2]) != reads[s] or int(row[3]) != mapped or int(row[6]) != zeros or int(row[5]) != len(col):
        fail("%s summary does not match the planted reads/mapped/zero counts" % s)
    if reads[s] - mapped != 3 * (mapped // 100):
        fail("%s: the unmapped reads are not exactly the planted mismatch + late + junk reads" % s)
    if row[7] != "{:.4g}".format(g) or not abs(gl - g) <= 1e-12 * g:
        fail("%s Gini %s / %r does not equal an independent recompute %r" % (s, row[7], gl, g))

# ---- test (RRA): median normalisation factors, recomputed ----------------------------------
def factors(cols):
    idx = [SAMPLES.index(c) for c in cols]
    m = {k: [v[1][i] for i in idx] for k, v in got.items()}
    gm = {k: math.exp(sum(math.log(c + 1.0) for c in v) / len(v)) for k, v in m.items() if sum(v) > 0}
    out = []
    for j in range(len(idx)):
        r = sorted(m[k][j] / gm[k] for k in gm)
        out.append(1.0 / r[len(r) // 2])
    return out
for name, cols in (("rra", ["ctrl1", "ctrl2", "treat1", "treat2"]), ("null", ["ctrl1", "ctrl2", "null1", "null2"])):
    lt = open(name + ".log").read()
    f = [float(x) for x in re.search(r"Final size factor: (.*)", lt).group(1).split()]
    mine = factors(cols)
    rel = max(abs(a - b) / b for a, b in zip(f, mine))
    rec("size_factors_" + name, " ".join("%.6f" % v for v in f), "(max rel diff vs recompute %.1e)" % rel)
    if len(f) != 4 or not rel <= 1e-12: fail("%s median size factors do not equal an independent recompute" % name)
# normalised counts are raw x factor
nh, nr = table("rra.normalized.txt")
f = [float(x) for x in re.search(r"Final size factor: (.*)", open("rra.log").read()).group(1).split()]
fac = dict(zip(["ctrl1", "ctrl2", "treat1", "treat2"], f))   # count-table column order
worst = max(abs(float(r[2 + j]) - got[r[0]][1][SAMPLES.index(c)] * fac[c]) / max(1.0, float(r[2 + j]))
            for r in nr for j, c in enumerate(nh[2:]))
rec("normalized_eq_raw_x_factor", "%.1e" % worst, "(max rel diff)")
if not worst <= 1e-12: fail("normalised counts are not raw counts x size factor")

# ---- test (RRA): planted genes rank first; null comparison discovers nothing ----------------
planted = {l.split("\t")[0]: l.split("\t")[1] for l in open("truth_genes.txt").read().splitlines()[1:]}
DEP = {g for g, p in planted.items() if p == "depleted"}; ENR = {g for g, p in planted.items() if p == "enriched"}
gh, gr = table("rra.gene_summary.txt"); H = {h: i for i, h in enumerate(gh)}
neg = sorted(gr, key=lambda r: int(r[H["neg|rank"]])); pos = sorted(gr, key=lambda r: int(r[H["pos|rank"]]))
top_neg = {r[0] for r in neg[:20]}; top_pos = {r[0] for r in pos[:20]}
rec("rra_neg_top20_planted_depleted", "%d/20" % len(top_neg & DEP))
rec("rra_pos_top20_planted_enriched", "%d/20" % len(top_pos & ENR))
if top_neg != DEP: fail("neg ranks 1-20 are not exactly the 20 planted depleted genes")
if top_pos != ENR: fail("pos ranks 1-20 are not exactly the 20 planted enriched genes")
mx_dep = max(float(r[H["neg|fdr"]]) for r in gr if r[0] in DEP)
mx_enr = max(float(r[H["pos|fdr"]]) for r in gr if r[0] in ENR)
fd_neg = sorted(r[0] for r in gr if planted.get(r[0]) == "null" and float(r[H["neg|fdr"]]) < 0.05)
fd_pos = sorted(r[0] for r in gr if planted.get(r[0]) == "null" and float(r[H["pos|fdr"]]) < 0.05)
rec("rra_planted_max_fdr", "depleted %g, enriched %g" % (mx_dep, mx_enr))
rec("rra_null_genes_fdr_lt_0.05", "neg %d %s, pos %d %s" % (len(fd_neg), fd_neg, len(fd_pos), fd_pos), "(observation)")
if not (mx_dep < 0.05 and mx_enr < 0.05): fail("a planted gene is not at FDR < 0.05 in its direction")
if "NonTargeting" in {r[0] for r in gr}: fail("non-targeting controls were scored as a gene")
nh2, nr2 = table("null.gene_summary.txt"); N = {h: i for i, h in enumerate(nh2)}
mn = min(float(r[N["neg|fdr"]]) for r in nr2); mp = min(float(r[N["pos|fdr"]]) for r in nr2)
pn = sum(1 for r in nr2 if float(r[N["neg|p-value"]]) < 0.05) / len(nr2)
rec("null_control_min_fdr", "neg %g, pos %g" % (mn, mp), "(no effect planted; nominal p<0.05 in %.1f%% of genes)" % (100 * pn))
if not (mn >= 0.05 and mp >= 0.05): fail("the null comparison found a gene at FDR < 0.05")
same = open("rra.gene_summary.txt").read() == open("rra_rep.gene_summary.txt").read()
rec("rra_rerun_byte_identical", same)
if not same: fail("RRA gave a different gene summary on an identical rerun")

# ---- mle: beta signs and order recover the planted design --------------------------------
mh2, mr2 = table("mle.gene_summary.txt"); M = {h: i for i, h in enumerate(mh2)}
beta = {r[0]: float(r[M["treatment|beta"]]) for r in mr2}
fdr = {r[0]: float(r[M["treatment|fdr"]]) for r in mr2}
order = sorted(beta, key=lambda g: beta[g])
dep_b = [beta[g] for g in DEP]; enr_b = [beta[g] for g in ENR]
rec("mle_beta_depleted", "%.3f .. %.3f" % (min(dep_b), max(dep_b)), "(planted ln(1/4) = -1.386)")
rec("mle_beta_enriched", "%.3f .. %.3f" % (min(enr_b), max(enr_b)), "(planted ln 4 = +1.386)")
rec("mle_beta_null_absmax", "%.3f" % max(abs(beta[g]) for g in beta if planted.get(g) == "null"))
rec("mle_planted_max_perm_fdr", "%g" % max(fdr[g] for g in DEP | ENR))
if not (max(dep_b) < 0 and min(enr_b) > 0): fail("an MLE beta has the wrong sign for a planted gene")
if set(order[:20]) != DEP or set(order[-20:]) != ENR: fail("the 20 most negative / positive MLE betas are not the planted genes")
if not max(fdr[g] for g in DEP | ENR) < 0.05: fail("a planted gene is not at MLE permutation FDR < 0.05")
if math.isnan(sum(beta.values())): fail("NaN in MLE betas")

if not ok: sys.exit(1)
print("MAGeCK OK")
PY
python3 -u check.py 2>&1 | tee smoke-check.txt
test "${PIPESTATUS[0]}" = 0 || { echo "FAIL: a MAGeCK check failed"; exit 1; }
uname -m | awk '{print "arch\t"$1}'
echo DONE
